<template>
  <BaseViewTemplate dark>
    <main
      id="comfy-login"
      class="relative min-w-84 rounded-lg bg-(--comfy-menu-bg) p-5 px-10 shadow-lg"
    >
      <h1 class="my-2.5 mb-7 font-normal">ComfyUI</h1>
      <div class="flex w-full flex-col items-center">
        <!-- 登录/注册切换标签 -->
        <div class="flex w-full mb-6">
          <button
            class="flex-1 py-2 text-center text-base font-medium border-b-2 transition-colors"
            :class="isLogin
              ? 'border-blue-500 text-blue-500'
              : 'border-transparent text-gray-400 hover:text-gray-300'"
            @click="isLogin = true"
          >
            {{ $t('login.login') }}
          </button>
          <button
            class="flex-1 py-2 text-center text-base font-medium border-b-2 transition-colors"
            :class="!isLogin
              ? 'border-blue-500 text-blue-500'
              : 'border-transparent text-gray-400 hover:text-gray-300'"
            @click="isLogin = false"
          >
            Register
          </button>
        </div>

        <!-- 用户名输入 -->
        <div class="flex w-full flex-col gap-2">
          <label for="username-input">{{ $t('login.username') }}:</label>
          <InputText
            id="username-input"
            v-model="username"
            :placeholder="$t('login.enterUsername')"
          />
        </div>
        
        <!-- 密码输入 -->
        <div class="flex w-full flex-col gap-2 mt-4">
          <label for="password-input">{{ $t('login.password') }}:</label>
          <Password
            id="password-input"
            v-model="password"
            :placeholder="$t('login.enterPassword')"
            :feedback="false"
            toggle-mask
            fluid
          />
        </div>

        <!-- 确认密码（仅注册时显示） -->
        <div v-if="!isLogin" class="flex w-full flex-col gap-2 mt-4">
          <label for="confirm-password-input">{{ $t('login.confirmPassword') }}:</label>
          <Password
            id="confirm-password-input"
            v-model="confirmPassword"
            :placeholder="$t('login.enterConfirmPassword')"
            :feedback="false"
            toggle-mask
            fluid
          />
        </div>
        
        <!-- 验证码 -->
        <div class="flex w-full flex-col gap-2 mt-4">
          <label for="captcha-input">{{ $t('login.captcha') }}:</label>
          <div class="flex gap-2 items-center">
            <InputText
              id="captcha-input"
              v-model="captcha"
              :placeholder="$t('login.enterCaptcha')"
              class="flex-1"
            />
            <img
              v-if="captchaImage"
              :src="captchaImage"
              alt="Captcha"
              class="h-10 w-28 cursor-pointer rounded border border-interface-stroke hover:border-interface-button-hover-surface"
              @click="refreshCaptcha"
              :title="$t('login.clickToRefresh')"
            />
          </div>
        </div>
        
        <!-- 错误消息 -->
        <Message v-if="error" severity="error" class="mt-4 w-full">
          {{ error }}
        </Message>

        <!-- 成功消息 -->
        <Message v-if="successMsg" severity="success" class="mt-4 w-full">
          {{ successMsg }}
        </Message>
        
        <!-- 提交按钮 -->
        <footer class="mt-5">
          <Button @click="isLogin ? handleLogin() : handleRegister()" :loading="loading">
            {{ isLogin ? $t('login.login') : 'Register' }}
          </Button>
        </footer>
      </div>
    </main>
  </BaseViewTemplate>
</template>

<script setup lang="ts">
import InputText from 'primevue/inputtext'
import Message from 'primevue/message'
import Password from 'primevue/password'
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'

import Button from '@/components/ui/button/Button.vue'
import { useUserStore } from '@/stores/userStore'
import { useBootstrapStore } from '@/stores/bootstrapStore'
import { useSettingStore } from '@/platform/settings/settingStore'
import BaseViewTemplate from '@/views/templates/BaseViewTemplate.vue'

const userStore = useUserStore()
const bootstrapStore = useBootstrapStore()
const settingStore = useSettingStore()
const router = useRouter()

const isLogin = ref(true)
const username = ref('')
const password = ref('')
const confirmPassword = ref('')
const captcha = ref('')
const captchaImage = ref('')
const captchaId = ref('')
const error = ref('')
const successMsg = ref('')
const loading = ref(false)

// 获取验证码
const refreshCaptcha = async () => {
  try {
    const response = await fetch('/api/captcha')
    captchaId.value = response.headers.get('X-Captcha-Id') || ''
    const blob = await response.blob()
    captchaImage.value = URL.createObjectURL(blob)
  } catch (err) {
    error.value = 'Failed to load captcha'
  }
}

// 登录
const handleLogin = async () => {
  if (!username.value || !password.value || !captcha.value) {
    error.value = 'Please fill in all fields'
    return
  }

  loading.value = true
  error.value = ''
  successMsg.value = ''

  try {
    // 调用登录API
    const response = await fetch('/api/v2/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        username: username.value,
        password: password.value,
        captcha: captcha.value,
        captcha_id: captchaId.value
      })
    })

    const data = await response.json()

    if (data.success) {
      // 使用userStore的login方法保存用户信息
      await userStore.login({
        userId: String(data.user_id),
        username: username.value
      })

      // 设置用户cookie
      await fetch('/api/set_user', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'comfy-user': String(data.user_id)
        },
        body: JSON.stringify({ user_id: data.user_id })
      })

      // Reset stores so they reload with the new user's data
      settingStore.resetLoadState()
      bootstrapStore.resetStoresLoaded()

      // Re-initialize user store and load authenticated stores
      await userStore.initialize()
      bootstrapStore.loadAuthenticatedStores()

      // 跳转到主页
      await router.push('/')
    } else {
      error.value = data.message || 'Login failed'
      // 刷新验证码
      await refreshCaptcha()
      captcha.value = ''
    }
  } catch (err) {
    error.value = err instanceof Error ? err.message : 'Login failed'
    await refreshCaptcha()
    captcha.value = ''
  } finally {
    loading.value = false
  }
}

// 注册
const handleRegister = async () => {
  if (!username.value || !password.value || !confirmPassword.value || !captcha.value) {
    error.value = 'Please fill in all fields'
    return
  }

  if (password.value !== confirmPassword.value) {
    error.value = 'Passwords do not match'
    return
  }

  if (password.value.length < 6) {
    error.value = 'Password must be at least 6 characters'
    return
  }

  loading.value = true
  error.value = ''
  successMsg.value = ''

  try {
    // 调用注册API
    const response = await fetch('/api/v2/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        username: username.value,
        password: password.value,
        captcha: captcha.value,
        captcha_id: captchaId.value
      })
    })

    const data = await response.json()

    if (data.success) {
      // 注册成功，切换到登录模式并提示
      successMsg.value = 'Registration successful! Please login with your credentials.'
      isLogin.value = true
      password.value = ''
      confirmPassword.value = ''
      captcha.value = ''
      await refreshCaptcha()
    } else {
      error.value = data.message || 'Registration failed'
      // 刷新验证码
      await refreshCaptcha()
      captcha.value = ''
    }
  } catch (err) {
    error.value = err instanceof Error ? err.message : 'Registration failed'
    await refreshCaptcha()
    captcha.value = ''
  } finally {
    loading.value = false
  }
}

onMounted(async () => {
  document.getElementById('splash-loader')?.remove()
  
  // 初始化用户store
  await userStore.initialize()
  
  // 加载验证码
  await refreshCaptcha()
})
</script>
